    #[test]
    fn generated_living_entity_use_item_tick() {
        let (m, id, _dir, lua) = loaded_tracked(
            "gen_living_entity_use_item_tick",
            "horizon.on(\"living_entity_use_item_tick\", function(event)\n    __witness = (__witness or 0) + 1\n    assert(event.stack.id == \"test:stack\", \"stack\")\n    assert(event.stack.count == 1, \"stack\")\n    assert(event.stack.damage == 0, \"stack\")\n    assert(event.stack.extra == nil, \"stack\")\n    assert(event.stack.plain == true, \"stack\")\n    assert(event.entity == 11, \"kind\")\n    assert(event.hand == \"main\", \"hand\")\n    assert(event.duration == 10, \"duration\")\n    event.duration = 53\n    horizon.cancel()\nend, \"minecraft:zombie\")",
        );
        let firing_mods = boxed(m);
        // K2 event: the handler stays quiet.
        {
            let mut duration = 10;
            let mut canceled = false;
            dispatch_living_entity_use_item_tick(
                &mut FakeHost::empty(),
                &firing_mods,
                &ItemStack {
                    item: "test:stack".into(),
                    count: 1,
                    damage: 0,
                    extra: None,
                },
                Some(13),
                Hand::Main,
                &mut duration,
                &mut canceled,
            );
            assert_eq!(witness(&lua), 0, "K2 event must not fire the handler");
        }
        no_error(&id);
        // gone event: the handler stays quiet.
        {
            let mut duration = 10;
            let mut canceled = false;
            dispatch_living_entity_use_item_tick(
                &mut FakeHost::empty(),
                &firing_mods,
                &ItemStack {
                    item: "test:stack".into(),
                    count: 1,
                    damage: 0,
                    extra: None,
                },
                None,
                Hand::Main,
                &mut duration,
                &mut canceled,
            );
            assert_eq!(witness(&lua), 0, "gone event must not fire the handler");
        }
        no_error(&id);
        let mut duration = 10;
        let mut canceled = false;
        dispatch_living_entity_use_item_tick(
            &mut FakeHost::empty(),
            &firing_mods,
            &ItemStack {
                item: "test:stack".into(),
                count: 1,
                damage: 0,
                extra: None,
            },
            Some(11),
            Hand::Main,
            &mut duration,
            &mut canceled,
        );
        assert!(canceled, "canceled not cancelled");
        assert_eq!(duration, 53);
        assert_eq!(witness(&lua), 1, "the handler ran");
        no_error(&id);
    }

