    #[test]
    fn generated_player_start_tracking() {
        let (m, id, _dir, lua) = loaded_tracked(
            "gen_player_start_tracking",
            "horizon.on(\"player_start_tracking\", function(event)\n    __witness = (__witness or 0) + 1\n    assert(event.player.uuid == \"00000000-0000-0000-0000-000000000007\", \"player\")\n    assert(event.player.name == \"test:name\", \"player\")\n    assert(event.entity == 9, \"entity\")\n    assert(event.uuid == 10, \"uuid\")\n    assert(event.kind == \"minecraft:zombie\", \"kind\")\nend, \"minecraft:zombie\")",
        );
        let firing_mods = boxed(m);
        // K2 event: the handler stays quiet.
        {
            dispatch_player_start_tracking(
                &mut FakeHost::empty(),
                &firing_mods,
                7,
                "test:name",
                9,
                10,
                "minecraft:skeleton",
            );
            assert_eq!(witness(&lua), 0, "K2 event must not fire the handler");
        }
        no_error(&id);
        dispatch_player_start_tracking(
            &mut FakeHost::empty(),
            &firing_mods,
            7,
            "test:name",
            9,
            10,
            "minecraft:zombie",
        );
        assert_eq!(witness(&lua), 1, "the handler ran");
        no_error(&id);
    }

    #[test]
    fn generated_player_start_tracking_unregistered_costs_nothing() {
        let (m, id, dir, lua) = loaded_tracked(
            "gen_player_start_tracking_cost",
            "horizon.on(\"tick\", function(event) end)",
        );
        let firing_mods = boxed(m);
        {
            reset_entity_reads();
            reset_host_reads();
            reset_level_reads();
            reset_event_tables();
            dispatch_player_start_tracking(
                &mut FakeHost::empty(),
                &firing_mods,
                7,
                "test:name",
                9,
                10,
                "test:kind",
            );
            assert_eq!(witness(&lua), 0, "no handler ran");
            assert_eq!(
                event_tables(),
                0,
                "no event table was built with no handler"
            );
            assert_eq!(
                entity_reads(),
                0,
                "player_start_tracking read the host with no handler"
            );
            assert_eq!(
                host_reads(),
                0,
                "player_start_tracking read the host with no handler"
            );
            assert_eq!(
                level_reads(),
                0,
                "player_start_tracking read the level with no handler"
            );
            no_error(&id);
            drop_dir(dir);
        }
        let (m, id, dir, lua) = loaded_tracked(
            "gen_player_start_tracking_cost_kind",
            "horizon.on(\"player_start_tracking\", function(event) end, \"minecraft:skeleton\")",
        );
        let firing_mods = boxed(m);
        {
            reset_entity_reads();
            reset_host_reads();
            reset_level_reads();
            reset_event_tables();
            dispatch_player_start_tracking(
                &mut FakeHost::empty(),
                &firing_mods,
                7,
                "test:name",
                9,
                10,
                "minecraft:zombie",
            );
            assert_eq!(witness(&lua), 0, "no handler ran");
            assert_eq!(
                event_tables(),
                0,
                "no event table is built for a watched-away kind (the table is built after the kind check)"
            );
            assert_eq!(
                entity_reads(),
                0,
                "player_start_tracking read the host for a watched-away kind"
            );
            assert_eq!(
                host_reads(),
                0,
                "player_start_tracking read the host for a watched-away kind"
            );
            assert_eq!(
                level_reads(),
                0,
                "player_start_tracking read the level for a watched-away kind"
            );
            no_error(&id);
            drop_dir(dir);
        }
        let (m, id, dir, lua) = loaded_tracked(
            "gen_player_start_tracking_cost_live",
            "horizon.on(\"player_start_tracking\", function(event)\n    __witness = (__witness or 0) + 1\nend, \"minecraft:zombie\")",
        );
        let firing_mods = boxed(m);
        {
            reset_entity_reads();
            reset_host_reads();
            reset_level_reads();
            reset_event_tables();
            dispatch_player_start_tracking(
                &mut FakeHost::empty(),
                &firing_mods,
                7,
                "test:name",
                9,
                10,
                "minecraft:zombie",
            );
            assert_eq!(witness(&lua), 1, "the control handler ran");
            assert!(
                event_tables() >= 1,
                "player_start_tracking built an event table for a heard dispatch"
            );
            assert!(
                host_reads() > 0,
                "player_start_tracking read the host for a heard dispatch"
            );
            assert_eq!(
                level_reads(),
                0,
                "player_start_tracking read the level for a heard dispatch"
            );
            no_error(&id);
            drop_dir(dir);
        }
    }

